    feature1Title: "புத்திசாலி நேர ஸ்லாட்டுகள்",
    feature1Desc: "குறைந்த கூட்ட நெரிசல் உள்ள நேரங்களை விவசாயிகள் தேர்ந்தெடுக்க வழிகாட்டுகிறது.",
    feature2Title: "நேரடி வரிசை கண்காணிப்பு",
    feature2Desc: "செயலில் உள்ள கவுண்டர்களின் அடிப்படையில் துல்லியமான வரிசை நிலை.",
    feature3Title: "வெளிப்படையான பில்லிங்",
    feature3Desc: "டிஜிட்டல் எடை ரசீது, தர நிர்ணயம் மற்றும் நேரடி எம்எஸ்பி கட்டணக் கண்காணிப்பு.",
    feature4Title: "கிசான் மித்ரா உதவியாளர்",
    feature4Desc: "11 இந்திய மொழிகளில் குரல் மற்றும் அரட்டை ஆதரவு.",
    howItWorksTitle: "இது எவ்வாறு செயல்படுகிறது",
    step1Title: "1. ஆன்லைனில் ஸ்லாட் பதிவு செய்",
    step1Desc: "பயிர், எடை மற்றும் குறைந்த கூட்ட நெரிசல் நேரத்தைத் தேர்ந்தெடுக்கவும்.",
    step2Title: "2. நேரடி வரிசையைக் கண்காணிக்கவும்",
    step2Desc: "உங்கள் நேரத்திற்கு 15 நிமிடங்களுக்கு முன் மண்டியை அடையுங்கள்.",
    step3Title: "3. விரைவு எடை மற்றும் தரம்",
    step3Desc: "கவுண்டர்களில் விரைவான எடை மற்றும் தரச் சரிபார்ப்பு.",
    step4Title: "4. கட்டணத்தைப் பெறுங்கள்",
    step4Desc: "டிஜிட்டல் ரசீது மற்றும் கட்டணக் குறிப்பு எண் உடனே கிடைக்கும்.",
    ctaTitle: "சிரமமில்லாத கொள்முதலை அனுபவிக்க தயாரா?",
