    faq1A: "'கொள்முதல் ஸ்லாட் பதிவு செய்' என்பதைக் கிளிக் செய்து மையம், பயிர், அளவு மற்றும் தேதியைத் தேர்ந்தெடுக்கவும். பச்சை நிற 'குறைந்த' நெரிசல் ஸ்லாட்டுகளைத் தேர்வு செய்யவும்.",
